209	static uint64_t read_reg64(struct qemu_plugin_register *h)
210	{
211	    if (!h) return 0;
212	    g_autoptr(GByteArray) buf = g_byte_array_new();
213	    int sz = qemu_plugin_read_register(h, buf);
214	    if (sz <= 0) return 0;
215	    uint64_t v = 0;
216	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
217	    return v;
218	}
