220	// Reads up to `dst_max` bytes from a register handle. Returns the byte
221	// count written (0 on failure or NULL handle). Used for vector regs whose
222	// width = vlenb bytes.
223	static size_t read_reg_bytes(struct qemu_plugin_register *h,
224	                             uint8_t *dst, size_t dst_max)
225	{
226	    if (!h || dst_max == 0) return 0;
227	    g_autoptr(GByteArray) buf = g_byte_array_new();
228	    int sz = qemu_plugin_read_register(h, buf);
229	    if (sz <= 0) return 0;
230	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
231	    memcpy(dst, buf->data, n);
232	    return n;
233	}
