235	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
236	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
237	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
238	// collide even under aggressive PID reuse (B13). The tmp lives in the
239	// same directory as `path` so the rename is intra-filesystem.
240	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
241	{
242	    char tmp[PATH_MAX];
243	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
244	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
245	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
246	        return -1;
247	    }
248	    int fd = g_mkstemp(tmp);
249	    if (fd < 0) {
250	        perror("hybrid_handoff: g_mkstemp");
251	        return -1;
252	    }
253	    // g_mkstemp creates the file 0600; no further chmod needed.
254	    ssize_t want = (ssize_t) sizeof(*s);
255	    ssize_t got = write(fd, s, sizeof(*s));
256	    if (got != want) {
257	        perror("hybrid_handoff: write");
258	        close(fd);
259	        unlink(tmp);
260	        return -1;
261	    }
262	    fsync(fd);
263	    close(fd);
264	    if (rename(tmp, path) != 0) {
265	        perror("hybrid_handoff: rename");
266	        unlink(tmp);
267	        return -1;
268	    }
269	    return 0;
270	}
