272	// Drain CPU state into `*s`. pc is computed by the caller (from a
273	// HandoffSite for trigger paths). If minstret_override is non-zero, it
274	// replaces QEMU's PMU minstret.
275	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
276	                             uint64_t minstret_override,
277	                             struct hybrid_state_v1 *sp)
278	{
279	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
280	    resolve_handles(v);
281	    memset(sp, 0, sizeof(*sp));
282	    struct hybrid_state_v1 s = {0};
283	    s.magic   = HYBRID_STATE_MAGIC;
284	    s.version = HYBRID_STATE_VERSION;
285	    s.flags   = HYBRID_FLAG_RV64;
286	    s.hart_id = vcpu_idx;
287	    // L6: real privilege at the boundary; M-mode fallback only when the
288	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
289	    // reads as 0 = U, which would silently demote the hart).
290	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
291	    s.pc      = pc;
292	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
293	
294	    // Floating-point: only set FP flag if at least one handle was bound,
295	    // i.e. QEMU advertised the FPU feature (D extension).
296	    int has_fp = 0;
297	    for (int i = 0; i < 32; i++) {
298	        s.fpr[i] = read_reg64(v->fpr[i]);
299	        if (v->fpr[i]) has_fp = 1;
300	    }
301	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
302	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
303	
304	    s.mstatus  = read_reg64(v->mstatus);
305	    s.mepc     = read_reg64(v->mepc);
306	    s.mtvec    = read_reg64(v->mtvec);
307	    s.mcause   = read_reg64(v->mcause);
308	    s.mtval    = read_reg64(v->mtval);
309	    s.mscratch = read_reg64(v->mscratch);
310	    s.medeleg  = read_reg64(v->medeleg);
311	    s.mideleg  = read_reg64(v->mideleg);
312	    s.mip      = read_reg64(v->mip);
313	    s.mie      = read_reg64(v->mie);
314	    s.mcycle   = read_reg64(v->mcycle);
315	    s.minstret = minstret_override ? minstret_override
316	                                   : read_reg64(v->minstret);
317	    s.satp     = read_reg64(v->satp);
318	
319	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
320	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
321	    s.mcache_ctl = read_reg64(v->mcache_ctl);
322	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
323	
324	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
325	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
326	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
327	    // handle on a non-Andes stub reads back as 0 -> tolerant.
328	    int has_andes = 0;
329	#define HYBRID_ANDES_FIELD(field, addr, name)  \
330	    s.andes.field = read_reg64(v->andes_##field); \
331	    if (v->andes_##field) has_andes = 1;
332	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
333	#undef HYBRID_ANDES_FIELD
334	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
335	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
336	        if (v->pmacfg[i]) has_andes = 1;
337	    }
338	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
339	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
340	        if (v->pmaaddr[i]) has_andes = 1;
341	    }
342	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
343	
344	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
345	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
346	    // reads 0. The vsim caps gate decides which of these the cycle engine
347	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
348	    int has_m_ext = 0;
349	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
350	    s.m_ext.field = read_reg64(v->m_ext_##field); \
351	    if (v->m_ext_##field) has_m_ext = 1;
352	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
353	#undef HYBRID_M_EXT_FIELD
354	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
355	
356	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
357	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
358	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
359	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
360	
361	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
362	    // bounds the per-register byte count copied into vreg[]. The policy
363	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
364	    // handle truthiness so we don't conflate "stub missing vlenb" with
365	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
366	    s.vstart = read_reg64(v->vstart);
367	    s.vxsat  = read_reg64(v->vxsat);
368	    s.vxrm   = read_reg64(v->vxrm);
369	    s.vcsr   = read_reg64(v->vcsr);
370	    s.vtype  = read_reg64(v->vtype);
371	    s.vl     = read_reg64(v->vl);
372	    s.vlenb  = read_reg64(v->vlenb);
373	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
374	                       || v->vtype || v->vl);
375	    if (!has_other_v) {
376	        for (int i = 0; i < 32; i++)
377	            if (v->vreg[i]) { has_other_v = 1; break; }
378	    }
379	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
380	        v->vlenb != NULL, has_other_v, s.vlenb);
381	    if (vpol == HYBRID_V_DRAIN_ABORT) {
382	        if (v->vlenb == NULL)
383	            fprintf(stderr,
384	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
385	                    "vlenb; refusing to drain partial V state\n");
386	        else
387	            fprintf(stderr,
388	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
389	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
390	                    "truncate V registers\n",
391	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
392	                    8 * HYBRID_VLEN_BYTES_MAX);
393	        exit(2);
394	    }
395	    if (vpol == HYBRID_V_DRAIN_OK) {
396	        s.flags |= HYBRID_FLAG_V;
397	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
398	         * full live register fits the wire-format slot -- no clamp (L11). */
399	        for (int i = 0; i < 32; i++)
400	            (void) read_reg_bytes(v->vreg[i],
401	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
402	                                  (size_t) s.vlenb);
403	    }
404	
405	    *sp = s;
406	}
407	
408	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
409	// exit(200).
410	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
411	                                uint64_t minstret_override, const char *path)
412	{
413	    struct hybrid_state_v1 s;
414	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
415	    if (write_state_atomic(&s, path) != 0) {
416	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
417	        exit(2);
418	    }
419	    fprintf(stderr,
420	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
421	            path, s.pc);
422	}
423	
424	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
425	// as the vsim resume point, and exit 200.
426	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
427	{
428	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
429	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
430	    // Distinguishes drain from workload completion (0) so the orchestrator
431	    // can decide the next spawn.
432	    exit(200);
433	}
434	
435	// Marker sites. The marker is an architectural NOP, so the pre-execution
436	// state equals the post-retire state and the window resumes AFTER it
437	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
438	// the exec callback can lag the actual current insn when V instructions
439	// retire just before the trigger -- TCG defers PC writes for performance).
440	static void on_handoff(unsigned int vcpu_idx, void *udata)
441	{
442	    const HandoffSite *site = (const HandoffSite *) udata;
443	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
444	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
445	}
446	
447	// pc boundary sites. Exec callbacks fire BEFORE the insn
448	// executes, and the boundary insn is real user code (unlike a marker NOP):
449	// the drained state must resume AT the boundary so the insn executes inside
450	// the vsim window rather than on neither leg. (Skipping it corrupts the
451	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
452	// set and the first vector op of the window faults.)
453	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
454	{
455	    const HandoffSite *site = (const HandoffSite *) udata;
456	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
457	    handoff_drain(vcpu_idx, site->vaddr);
458	}
459	
460	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
461	// When armed (the exit boundary's own tick ran), this tick fires before its
462	// insn executes, so a drain here records the post-retire state of the
463	// boundary insn with pc = the dynamically-next insn's vaddr.
464	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
465	{
466	    const HandoffSite *site = (const HandoffSite *) udata;
467	    if (oracle_armed
468	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
469	        handoff_drain(vcpu_idx, site->vaddr);
470	    }
471	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
472	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
473	        oracle_armed = 1;
474	    }
475	}
476	
477	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
478	{
479	    (void) id;
480	    size_t n = qemu_plugin_tb_n_insns(tb);
481	
482	    for (size_t i = 0; i < n; i++) {
483	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
484	
485	        // Oracle exit-drain mode: exclusive with every other mode (enforced
486	        // at install), so it owns the insn's registration outright. The site
487	        // carries the marker kind so the tick can arm on the EXIT marker.
488	        if (exit_marker_mode || exit_pc_mode) {
489	            HandoffSite *site = g_new0(HandoffSite, 1);
490	            site->kind  = HYBRID_HANDOFF_NONE;
491	            site->vaddr = qemu_plugin_insn_vaddr(insn);
492	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
493	            if (exit_marker_mode && site->size == 4) {
494	                uint32_t raw = 0;
495	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
496	                    hybrid_match_handoff_insn(raw, &site->kind);
497	            }
498	            qemu_plugin_register_vcpu_insn_exec_cb(
499	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
500	            continue;
501	        }
502	
503	        if (pc_mode) {
504	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
505	            // boundary (on_handoff_boundary), so the insn size is recorded
506	            // only for completeness.
507	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
508	            HandoffSite *site = g_new0(HandoffSite, 1);
509	            site->kind  = HYBRID_HANDOFF_ENTER;
510	            site->vaddr = qemu_plugin_insn_vaddr(insn);
511	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
512	            qemu_plugin_register_vcpu_insn_exec_cb(
513	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
514	            continue;
515	        }
516	
517	        // Marker-trigger mode (default).
518	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
519	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
520	        // exact, not an approximation.
521	        size_t sz = qemu_plugin_insn_size(insn);
522	        if (sz != 4) continue;
523	        uint32_t raw = 0;
524	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
525	            continue;
526	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
527	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
528	        HandoffSite *site = g_new0(HandoffSite, 1);
529	        site->kind  = kind;
530	        site->vaddr = qemu_plugin_insn_vaddr(insn);
531	        site->size  = (uint32_t) sz;
532	        qemu_plugin_register_vcpu_insn_exec_cb(
533	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
534	    }
535	}
536	
537	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
538	                                           const qemu_info_t *info,
539	                                           int argc, char **argv)
540	{
541	    (void) info;
542	    for (int i = 0; i < argc; i++) {
543	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
544	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
545	            outfile_path = g_strdup(tok[1]);
546	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
547	            char *endp = NULL;
548	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
549	            if (!endp || *endp != '\0') {
550	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
551	                        tok[1]);
552	                return -1;
553	            }
554	            enter_pc_arg = (uint64_t) v;
555	            pc_mode = 1;
556	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
557	            char *endp = NULL;
558	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
559	            if (!endp || *endp != '\0') {
560	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
561	                        tok[1]);
562	                return -1;
563	            }
564	            exit_pc_arg = (uint64_t) v;
565	            exit_pc_mode = 1;
566	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
567	            char *endp = NULL;
568	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
569	            if (!endp || *endp != '\0') {
570	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
571	                        tok[1]);
572	                return -1;
573	            }
574	            exit_marker_mode = (v != 0);
575	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
576	            char *endp = NULL;
577	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
578	            if (!endp || *endp != '\0') {
579	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
580	                        tok[1]);
581	                return -1;
582	            }
583	            drain_pc_arg = (uint64_t) v;
584	            drain_pc_set = 1;
585	        } else {
586	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
587	            return -1;
588	        }
589	    }
590	    if (!outfile_path) {
591	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
592	        return -1;
593	    }
594	    if (pc_mode) {
595	        fprintf(stderr,
596	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
597	                enter_pc_arg);
598	    }
599	    if (exit_marker_mode || exit_pc_mode) {
600	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
601	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
602	                  "is exclusive with the other trigger modes\n", stderr);
603	            return -1;
604	        }
605	        if (exit_pc_mode) {
606	            fprintf(stderr,
607	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
608	                    PRIx64 "\n", exit_pc_arg);
609	        } else {
610	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
611	                  stderr);
612	        }
613	        if (drain_pc_set) {
614	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
615	                    drain_pc_arg);
616	        }
617	    } else if (drain_pc_set) {
618	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
619	              "(exit_marker/exit_pc)\n", stderr);
620	        return -1;
621	    }
622	
623	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
624	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
625	    return 0;
626	}
